mapper.select:
select ca.*, t.teacher_name as teacherName, r.room_name as preferRoomName, co.college_name as collegeName, c.course_code as createdCourseCode from course_apply ca left join teacher t on ca.teacher_id = t.teacher_id left join room r on ca.prefer_room_id = r.id left join college co on ca.college_id = co.id left join course c on ca.created_course_id = c.id
and ca.teacher_id = #{teacherId}
and ca.status = #{status}
and ca.term = #{term}
order by ca.id desc
